import{_ as e,o,c as t,a3 as r}from"./chunks/framework.CJlOecQn.js";const u=JSON.parse('{"title":"Public holidays and Ramadan working hours","description":"Holiday entitlement for private-sector workers, how holiday notices reach you, Ramadan working hours and what to keep in mind during the holy month.","frontmatter":{"title":"Public holidays and Ramadan working hours","description":"Holiday entitlement for private-sector workers, how holiday notices reach you, Ramadan working hours and what to keep in mind during the holy month.","lastChecked":"2026-10","sourceCount":5},"headers":[],"relativePath":"guide/holidays-and-ramadan.md","filePath":"guide/holidays-and-ramadan.md"}'),n={name:"guide/holidays-and-ramadan.md"};function s(i,a,f,l,h,d){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="public-holidays-and-ramadan-working-hours" tabindex="-1">Public holidays and Ramadan working hours <a class="header-anchor" href="#public-holidays-and-ramadan-working-hours" aria-label="Permalink to &quot;Public holidays and Ramadan working hours&quot;">​</a></h1><p>This page covers the paid holidays private-sector workers are entitled to, the shorter hours during Ramadan, and how to behave respectfully during the month. The holiday and hours rules come from the National Human Rights Committee&#39;s Worker&#39;s Pocket Booklet of December 2021, so check for later changes.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><h2 id="paid-holidays-in-the-private-sector" tabindex="-1">Paid holidays in the private sector <a class="header-anchor" href="#paid-holidays-in-the-private-sector" aria-label="Permalink to &quot;Paid holidays in the private sector&quot;">​</a></h2><p>The booklet lists these days as holidays with full pay:<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><ul><li>Eid al-Fitr: three days.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>Eid al-Adha: three days.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>National Day: one day, on 18 December.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>Three more days, with dates set by your employer.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li></ul><p>If the work requires you to work on any of these days, you must be compensated.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></p><h2 id="national-sport-day" tabindex="-1">National Sport Day <a class="header-anchor" href="#national-sport-day" aria-label="Permalink to &quot;National Sport Day&quot;">​</a></h2><p>Qatar Central Bank&#39;s notice for 2024 called National Sport Day, Tuesday 13 February 2024, an official holiday, with financial institutions reopening the next day. Check each year&#39;s notice for the date, and ask your employer whether it applies to you, because the booklet&#39;s list does not name this day.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><h2 id="how-holiday-dates-reach-you" tabindex="-1">How holiday dates reach you <a class="header-anchor" href="#how-holiday-dates-reach-you" aria-label="Permalink to &quot;How holiday dates reach you&quot;">​</a></h2><p>Qatar Central Bank posts its own notices for financial institutions on its website, such as its National Day circular for 2024 and its National Sport Day notice for 2024. Use these to see when banks will close.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><h2 id="working-hours-in-ramadan" tabindex="-1">Working hours in Ramadan <a class="header-anchor" href="#working-hours-in-ramadan" aria-label="Permalink to &quot;Working hours in Ramadan&quot;">​</a></h2><ul><li>Private sector: the booklet gives six working hours a day during Ramadan, with a break that does not count as working time.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li>Banks and other financial institutions: for Ramadan 2026 (1447 AH), Qatar Central Bank set five hours a day, from 9:00 AM to 2:00 PM. This can change from year to year.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li></ul><p>Ramadan starts with the sighting of the crescent moon and lasts about 29 or 30 days, so the dates change every year.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></p><h2 id="during-ramadan" tabindex="-1">During Ramadan <a class="header-anchor" href="#during-ramadan" aria-label="Permalink to &quot;During Ramadan&quot;">​</a></h2><p>Visit Qatar gives this advice for visitors, and it is a sensible guide for new residents too.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></p><ul><li>Avoid eating, drinking or smoking in public during daylight fasting hours.<sup class="footnote-ref"><a href="#fn5" id="fnref5:2">[5]</a></sup></li><li>Avoid loud music and offensive language.<sup class="footnote-ref"><a href="#fn5" id="fnref5:3">[5]</a></sup></li><li>Dress modestly in public places. Light clothing that covers the shoulders and knees is generally recommended.<sup class="footnote-ref"><a href="#fn5" id="fnref5:4">[5]</a></sup></li><li>Check opening times before you go out, as attractions, restaurants and shops may change their hours.<sup class="footnote-ref"><a href="#fn5" id="fnref5:5">[5]</a></sup></li><li>If you are not fasting, many hotels, restaurants and designated dining areas still serve food.<sup class="footnote-ref"><a href="#fn5" id="fnref5:6">[5]</a></sup></li></ul><p>See also: <a href="./work-and-labour-rights">Work and labour rights</a>, <a href="./banking-and-money">Banking and money transfers</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>National Human Rights Committee, <a href="https://www.nhrc-qa.org/storage/publications/file_6666d6f57f82d_1718015733.pdf" target="_blank" rel="noreferrer">Worker&#39;s Pocket Booklet, sixth edition, December 2021</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Qatar Central Bank, <a href="https://www.qcb.gov.qa/en/news/pages/12feb24.aspx" target="_blank" rel="noreferrer">National Sport Holiday Announcement</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Qatar Central Bank, <a href="https://www.qcb.gov.qa/en/News/pages/16dec.aspx" target="_blank" rel="noreferrer">Circular on the occasion of Qatar National Day 2024</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Qatar Central Bank, <a href="https://www.qcb.gov.qa/en/News/Pages/ramadan2026.aspx" target="_blank" rel="noreferrer">Working Hours During Ramadan</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Visit Qatar, <a href="https://visitqatar.com/intl-en/about-qatar/traditions/ramadan" target="_blank" rel="noreferrer">Ramadan traditions in Qatar</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:6" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',20)])])}const p=e(n,[["render",s]]);export{u as __pageData,p as default};
